// 1. GET INPUTS
const webhookItem = $('Webhook: Receive Recurring Booking').first().json;
const input = webhookItem.body || webhookItem;
const room = $input.first().json;

// 2. VALIDATION
if (!room || !room.id) throw new Error("Room not found for id: " + (input.room_id || 'unknown'));
if (!input.customer_id) throw new Error("Customer ID missing.");
if (!input.booking_date) throw new Error("booking_date missing from request.");

// 3. TRUST FRONTEND-CALCULATED AMOUNTS
const total_amount = parseFloat(input.total_amount) || 0;
if (isNaN(total_amount) || total_amount < 0) {
  throw new Error("Invalid total_amount received: " + input.total_amount);
}

// Pending bookings have payment_type='none' and payment_amount=0
const isPending = input.status === 'pending' || input.payment_type === 'none';
const pType = isPending ? 'none' : (input.payment_type === 'full' || input.payment_type === 'full_payment') ? 'full' : 'deposit';
let payment_amount = parseFloat(input.payment_amount) || 0;
if (!isPending) {
  if (isNaN(payment_amount) || payment_amount <= 0) {
    throw new Error("Invalid payment_amount received: " + input.payment_amount);
  }
}
if (pType === 'full') payment_amount = total_amount;
if (isPending) payment_amount = 0;

const balance = total_amount - payment_amount;
const status = isPending ? 'pending' : (balance <= 0.01 ? 'fully_paid' : 'deposit_paid');

// 4. GENERATE REFS
const txnRef = 'TXN-REC-' + Math.floor(100000 + Math.random() * 900000);
const startDateTime = input.booking_date + 'T' + input.start_time + ':00';
const endDateTime   = input.booking_date + 'T' + input.end_time   + ':00';

return {
  json: {
    ...input,
    room_id:            room.id,
    total_amount:       parseFloat(total_amount.toFixed(2)),
    payment_amount:     parseFloat(payment_amount.toFixed(2)),
    balance_due:        parseFloat(balance.toFixed(2)),
    booking_status:     status,
    payment_type_clean: pType,
    payment_date:       new Date().toISOString(),
    customer_id:        input.customer_id.toString(),
    txn_reference:      txnRef,
    request_id:         (input.request_id && input.request_id !== "") ? input.request_id : null,
    google_start:       startDateTime,
    google_end:         endDateTime,
    is_recurring:       input.is_recurring === true || input.is_recurring === 'true' || false,
    recurring_rule_id:  input.recurring_rule_id || null,
    series_label:       input.series_label || 'Recurring'
  }
};
